head.script:
scwin.init = function() {
    var jsonData = [{
            'col2': "autoFitFilterList is True autoFitFilterList is True",
            'col3': "1"
        },
        {
            'col2': "sample001",
            'col3': "2"
        },
        {
            'col2': "sample002",
            'col3': "3"
        },
        {
            'col2': "sample002",
            'col3': "4"
        },
        {
            'col2': "sample002",
            'col3': "5"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.gridView1_onviewchange = function(info) {
    var col = dataList1.getColumnID(info.colIndex);
    if (col == "col3") {
        gridView1.setCellChecked(info.rowIndex, "col1", true);
    }
    txta.setValue(JSON.stringify(dataList1.getAllJSON()));
};
scwin.grid1_ongroupby = function(options) {
    options.closeGroup = true;
    options.groupbyHeader = [{
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    }];
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    //				return false;
    //				return true;
}
scwin.gridView1_oncellclick = function(row, col) {
    console.log(gridView1.getFocusedRowIndex());
    console.log(dataList1.getCellData(gridView1.getFocusedRowIndex(), 'col3'));
};
scwin.checkVal1 = function() {
    return ((j) => j.length ? j : $('#mf_gridView1_cell_0_0'))($('#gridView1_cell_0_0')).text() == 'autoFitFilterList is True autoFitFilterList is True    [ 1 건 ]  ';
}
scwin.checkVal2 = function() {
    return ((j) => j.length ? j : $('#mf_gridView1_cell_2_0'))($('#gridView1_cell_2_0')).text() == 'sample001    [ 1 건 ]  ';
}
scwin.checkVal3 = function() {
    return ((j) => j.length ? j : $('#mf_gridView1_cell_4_0'))($('#gridView1_cell_4_0')).text() == 'sample002    [ 3 건 ]  ';
}
scwin.checkVal4 = function() {
    return ((j) => j.length ? j : $('#mf_gridView1_groupbyZone_list'))($('#gridView1_groupbyZone_list')).width() >= ((j) => j.length ? j : $('.mf_w2grid_groupbyZone_list_listRow:nth-child(3) span'))($('.w2grid_groupbyZone_list_listRow:nth-child(3) span')).width();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
}
